func ParseNodeRole(s string) (NodeRole, error) {
  switch NodeRole(s) {
  case RoleBootstrap, RoleMaster, RoleWorker:
    return NodeRole(s), nil
  default:
    return "", fmt.Errorf("unknown node role %q (want bootstrap|master|worker)", s)
  }
}

